import React from 'react';
import {
  Box,
  Step,
  StepLabel,
  Stepper,
  Typography,
  Alert,
} from '@mui/material';
import type { TimelineStep } from '../../utils/applicationTimeline';
import { useResponsiveStepperOrientation } from '../../hooks/useResponsiveStepperOrientation';

export interface ApplicationStatusTimelineProps {
  steps: TimelineStep[];
  submittedAt?: string | Date;
  slaDays?: number;
  contactEmail?: string;
  reviewComments?: string;
}

const ApplicationStatusTimeline: React.FC<ApplicationStatusTimelineProps> = ({
  steps,
  submittedAt,
  slaDays,
  contactEmail,
  reviewComments,
}) => {
  const activeIdx = steps.findIndex((s) => s.state === 'active' || s.state === 'error');
  const activeStep = activeIdx >= 0 ? activeIdx : 0;
  const { orientation, alternativeLabel } = useResponsiveStepperOrientation();

  return (
    <Box sx={{ mt: 2, mb: 2 }}>
      <Typography variant="subtitle2" sx={{ fontWeight: 700, mb: 1.5 }}>
        Application progress
      </Typography>
      <Stepper activeStep={activeStep} orientation={orientation} alternativeLabel={alternativeLabel} sx={{ mb: 2 }}>
        {steps.map((step) => (
          <Step key={step.key} completed={step.state === 'complete'}>
            <StepLabel
              error={step.state === 'error'}
              optional={
                step.state === 'active' ? (
                  <Typography variant="caption">{step.description}</Typography>
                ) : undefined
              }
            >
              {step.label}
            </StepLabel>
          </Step>
        ))}
      </Stepper>
      {submittedAt && slaDays ? (
        <Alert severity="info" sx={{ mb: 1 }}>
          Submitted on {new Date(submittedAt).toLocaleDateString('en-IN')}. Typical review time is
          about {slaDays} business days.
          {contactEmail ? ` Questions? Contact ${contactEmail}.` : ''}
        </Alert>
      ) : null}
      {reviewComments ? (
        <Typography variant="body2" color="text.secondary">
          Reviewer note: {reviewComments}
        </Typography>
      ) : null}
    </Box>
  );
};

export default ApplicationStatusTimeline;
