import React from 'react';
import { Box, Button, Typography } from '@mui/material';

export interface TabSectionNavLinksProps {
  tabLabels: string[];
  currentIndex: number;
  onNavigate: (index: number) => void;
  /** Shown before the link buttons (default: "Continue to") */
  prefix?: string;
}

/**
 * Renders text buttons for every tab after the current one, for quick navigation
 * without scrolling back to the tab strip.
 */
const TabSectionNavLinks: React.FC<TabSectionNavLinksProps> = ({
  tabLabels,
  currentIndex,
  onNavigate,
  prefix = 'Continue to',
}) => {
  const nextIndices = tabLabels
    .map((_, i) => i)
    .filter((i) => i > currentIndex);

  if (nextIndices.length === 0) {
    return null;
  }

  return (
    <Box
      sx={{
        display: 'flex',
        flexWrap: 'wrap',
        alignItems: 'center',
        gap: 0.5,
        rowGap: 0.25,
        py: 1,
        px: { xs: 1, sm: 2 },
        bgcolor: (theme) =>
          theme.palette.mode === 'light' ? 'rgba(0,0,0,0.02)' : 'rgba(255,255,255,0.03)',
      }}
    >
      <Typography component="span" variant="caption" color="text.secondary" sx={{ mr: 0.5 }}>
        {prefix}
      </Typography>
      {nextIndices.map((idx, i) => (
        <React.Fragment key={`${tabLabels[idx]}-${idx}`}>
          {i > 0 && (
            <Typography component="span" variant="caption" color="text.disabled" sx={{ px: 0.25 }}>
              ·
            </Typography>
          )}
          <Button
            size="small"
            variant="text"
            onClick={() => onNavigate(idx)}
            sx={{ minWidth: 'auto', textTransform: 'none', px: 0.5, py: 0.25 }}
            aria-label={`Open ${tabLabels[idx]} tab`}
          >
            {tabLabels[idx]}
          </Button>
        </React.Fragment>
      ))}
    </Box>
  );
};

export default TabSectionNavLinks;
